func (this *Test_org_eclipse_swt_graphics_RGBA) Test_equalsLjava_lang_Object() {
	var r int32 = 0
	var g int32 = 127
	var b int32 = 254
	var a int32 = 254
	var rgba1 *swt.RGBA = swt.NewRGBA(r, g, b, a)
	var rgba2 *swt.RGBA
	rgba2 = rgba1
	if !rgba1.Equals(rgba2) {
		junit.Fail("Two references to the same RGBA instance not found equal")
	}
	rgba2 = swt.NewRGBA(r, g, b, a)
	if !rgba1.Equals(rgba2) {
		junit.Fail("References to two different RGBA instances with same R G B A parameters not found equal")
	}
	if rgba1.Equals(swt.NewRGBA(r+1, g, b, a)) || rgba1.Equals(swt.NewRGBA(r, g+1, b, a)) || rgba1.Equals(swt.NewRGBA(r, g, b+1, a)) || rgba1.Equals(swt.NewRGBA(r, g, b, a+1)) || rgba1.Equals(swt.NewRGBA(r+1, g+1, b+1, a+1)) {
		junit.Fail("Comparing two RGBA instances with different combination of R G B A parameters found equal")
	}
	var hue float32 = 220.0
	var sat float32 = 0.6
	var bright float32 = 0.7
	var alpha float32 = 0.5
	rgba1 = swt.NewRGBAHueSaturationBrightnessAlpha(hue, sat, bright, alpha)
	rgba2 = rgba1
	if !rgba1.Equals(rgba2) {
		junit.Fail("Two references to the same RGBA instance not found equal")
	}
	rgba2 = swt.NewRGBAHueSaturationBrightnessAlpha(hue, sat, bright, alpha)
	if !rgba1.Equals(rgba2) {
		junit.Fail("References to two different RGBA instances with same H S B A parameters not found equal")
	}
	if rgba1.Equals(swt.NewRGBAHueSaturationBrightnessAlpha(hue+1, sat, bright, alpha)) || rgba1.Equals(swt.NewRGBAHueSaturationBrightnessAlpha(hue, sat+0.1, bright, alpha)) || rgba1.Equals(swt.NewRGBAHueSaturationBrightnessAlpha(hue, sat, bright+0.1, alpha)) || rgba1.Equals(swt.NewRGBAHueSaturationBrightnessAlpha(hue, sat, bright, alpha+1.0)) || rgba1.Equals(swt.NewRGBAHueSaturationBrightnessAlpha(hue+1, sat+0.1, bright+0.1, alpha+1.0)) {
		junit.Fail("Comparing two RGBA instances with different combination of H S B A parameters found equal")
	}
}

