func (this *Test_org_eclipse_swt_graphics_RGBA) Test_hashCode() {
	var r int32 = 255
	var g int32 = 100
	var b int32 = 0
	var a int32 = 0
	var different int32 = 150
	var rgba1 *swt.RGBA = swt.NewRGBA(r, g, b, a)
	var rgba2 *swt.RGBA = swt.NewRGBA(r, g, b, a)
	var hash1 int32 = rgba1.HashCode()
	var hash2 int32 = rgba2.HashCode()
	junit.AssertEquals(int32(hash1), int32(hash2), "Two RGBA instances with same R G B A parameters returned different hash codes")
	junit.AssertTrue(rgba1.HashCode() != swt.NewRGBA(g, b, r, a).HashCode() && rgba1.HashCode() != swt.NewRGBA(b, r, g, a).HashCode(), "Two RGB instances with different R G B A parameters returned the same hash code")
	junit.AssertNotEquals(int32(rgba1.HashCode()), int32(swt.NewRGBA(different, g, b, a).HashCode()), "Two RGBA instances with different RED parameters returned the same hash code")
	junit.AssertNotEquals(int32(rgba1.HashCode()), int32(swt.NewRGBA(r, different, b, a).HashCode()), "Two RGBA instances with different GREEN parameters returned the same hash code")
	junit.AssertNotEquals(int32(rgba1.HashCode()), int32(swt.NewRGBA(r, g, different, a).HashCode()), "Two RGBA instances with different BLUE parameters returned the same hash code")
	junit.AssertNotEquals(int32(rgba1.HashCode()), int32(swt.NewRGBA(r, g, b, different).HashCode()), "Two RGBA instances with different ALPHA parameters returned the same hash code")
}

